/* ---------- v4.4 survival mode: mill leader portraits (the art only; the roster and the dialogs are in 09c-leaders.js) ----------
   Painted portraits, one WebP per leader at 408 x 460, embedded so the game stays a single file. They are shown as CSS
   backgrounds (one decode each, however many cards are on screen): leadArt(id) is the card portrait, leadArt(id,true)
   the round face for the wave chip and the outage dialog. LEAD_FACE is the square that frames each face: x, y, size.
   To replace a portrait: export it at 408 x 460, base64 it here, and set its face square. */
const LEAD_AW=408,LEAD_AH=460;
const LEAD_FACE={chip:[78,24,244],dot:[88,50,236],fel:[74,52,250],hank:[80,48,250]};
const LEAD_IMG={
  chip:"data:image/webp;base64,",
  dot:"data:image/webp;base64,",
  fel:"data:image/webp;base64,",
  hank:"data:image/webp;base64,"};
{const st=document.createElement("style");st.id="leadArtCss";
  st.textContent=Object.keys(LEAD_IMG).map(id=>{const [x,y,s]=LEAD_FACE[id];
    return `.ldart[data-a="${id}"]{background-image:url(${LEAD_IMG[id]})}.ldart.face[data-a="${id}"]{background-size:${(LEAD_AW/s*100).toFixed(2)}% auto;background-position:${(x/(LEAD_AW-s)*100).toFixed(2)}% ${(y/(LEAD_AH-s)*100).toFixed(2)}%}`;}).join("");
  document.head.appendChild(st);}
const leadArt=(id,face)=>`<span class="ldart${face?" face":""}" data-a="${id}" role="img" aria-label="${escHTML(LEADERS[id].name)}"></span>`;
